def solve_by_shift_9_block_down(grid):
    h, w = len(grid), len(grid[0])
    new_grid = [[3]*w for _ in range(h)]

    # Place 9-block shifted down by 2
    for r in range(7):
        for c in range(2):
            val = grid[r][c]
            if val != 3:
                new_grid[r+2][c] = val

    # Place left 2-block
    for r in range(2, 9):
        for c in range(4, 6):
            val = grid[r][c]
            if val != 3:
                new_grid[r][c] = val

    # Place right 2-block
    for r in range(2, 9):
        for c in range(7, 11):
            val = grid[r][c]
            if val != 3:
                new_grid[r][c] = val

    # Place markers
    for c in range(w):
        val = grid[10][c]
        if val != 3:
            new_grid[10][c] = val

    return new_grid

